#endif

    if (a > b) {
        printf("The first integer is greater than the second integer.\n");
    } else if (a < b) {
        printf("The first integer is less than the second integer.\n");
    } else {
        printf("The two integers are equal.\n");
    }

    return 0;
#if defined(WIN32) || defined(_WIN32)
    system("pause");
#endif
